const obj = {
  name: 'Alice',
  greet() { console.log(this.name); },           // implicit
  greetArrow: () => console.log(this.name),      // lexical (window.name)
};
obj.greet();         // 'Alice'
obj.greetArrow();    // undefined (global this)

const fn = obj.greet;
fn();                // undefined (strict) or '' (window.name)
fn.call({ name: 'Bob' }); // 'Bob' — explicit binding

class Timer {
  constructor() {
    this.seconds = 0;
    // Arrow captures 'this' (the Timer instance) at definition time:
    setInterval(() => this.seconds++, 1000); // correct!

    // Regular function would lose 'this':
    // setInterval(function() { this.seconds++; }, 1000); // broken!
  }
}

// Arrow as prototype method — WRONG:
function Cat(name) { this.name = name; }
Cat.prototype.speak = () => this.name; // 'this' is global here!
new Cat('Whiskers').speak(); // undefined
